@import "tailwindcss" source(none);
@import "tw-animate-css";
@source "../src";

@custom-variant dark (&:is(.dark *));

/*
 * ════════════════════════════════════════
 *  CLOSER — DESIGN SYSTEM
 * ════════════════════════════════════════
 *
 *  Filosofía visual:
 *  - Oscuro siempre, con profundidad: fondo azul marino casi negro y tres
 *    niveles de superficie claramente distintos. Nada de morado.
 *  - TODOS los colores viven aquí, en :root (--c-…). Las pantallas no
 *    escriben colores a mano: usan var(--c-…), o rgb(var(--c-…-rgb) / 0.4)
 *    para transparencia. Cambiar un color = cambiar UNA línea de este archivo.
 *    (Fase 1 del rediseño, mensaje 145, nov-2026.)
 *  - Naranja #FF6B2B = ÚNICA señal de "acción principal / avanza".
 *    Sagrado. No usar para decoración.
 *  - Radios: 14px en cards (pro accesible), 99px en botones (acción).
 *  - Tipografías: Syne (autoridad/títulos/CTAs), DM Sans (cuerpo denso).
 *  - Mobile-first. Max-width contenido 560px. Padding lateral 1.2rem.
 */


@theme inline {
  /* Radios */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 14px;          /* cards — base profesional accesible */
  --radius-xl: 18px;
  --radius-2xl: 24px;
  --radius-full: 99px;        /* botones — acción */

  /* Colores semánticos → Tailwind utilities */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-surface-elevated: var(--surface-elevated);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary-glow: var(--primary-glow);
  --color-primary-soft: var(--primary-soft);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);

  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* Niveles de score */
  --color-score-low: var(--score-low);
  --color-score-mid: var(--score-mid);
  --color-score-high: var(--score-high);

  /* Coach */
  --color-coach: var(--coach);
  --color-coach-foreground: var(--coach-foreground);

  /* Gradientes y sombras */
  --gradient-primary: var(--gradient-primary);
  --gradient-fire: var(--gradient-fire);
  --gradient-surface: var(--gradient-surface);
  --shadow-orange: var(--shadow-orange);
  --shadow-card: var(--shadow-card);
  --shadow-elevated: var(--shadow-elevated);

  /* Tipografía */
  --font-display: "Syne", system-ui, sans-serif;
  --font-sans: "DM Sans", system-ui, sans-serif;

  /* Animaciones */
  --animate-pulse-orange: pulse-orange 2s ease-in-out infinite;
  --animate-fade-up: fade-up 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-slide-down: slide-down 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-score-fill: score-fill 1.2s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  --animate-breathe: breathe 3.5s ease-in-out infinite;
}

/*
 * Closer es oscuro por filosofía. Los tokens viven en :root sin distinguir
 * claro/oscuro.
 */
:root {
  /* ═══ LA PALETA DE CLOSER — la única fuente de color de la app ═══ */
  /* Fondos: azul marino casi negro, y tres niveles de profundidad */
  --c-bg: #060A14;            --c-bg-rgb: 6 10 20;
  --c-bg-glow: #0D1730;       /* resplandor sutil detrás de la entrada */
  --c-surface: #0D1322;       --c-surface-rgb: 13 19 34;
  --c-elevated: #151D31;      --c-elevated-rgb: 21 29 49;
  --c-border: #212A3F;
  --c-border-strong: #2D3852;
  /* Texto */
  --c-text: #F3F5F9;          --c-text-rgb: 243 245 249;
  --c-text-soft: #C3C9D6;
  --c-text-2: #8A93A8;        /* secundario: legible, sin morado */
  /* Acción: el naranja de Closer. Solo para «avanza». */
  --c-primary: #FF6B2B;       --c-primary-rgb: 255 107 43;
  --c-primary-hover: #FF7D45;
  /* El botón de play (Fase 3): naranja con volumen. El centro va un poco más hondo
     que la marca para que el ícono blanco pase el contraste (3.2 a 1). */
  --c-play-claro: #FF8A50;  --c-play-centro: #F4601F;  --c-play-hondo: #E8540F;
  --c-play-sombra-rgb: 160 50 0;
  /* El cliente (y la demostración): azul */
  --c-client: #4DABF7;        --c-client-rgb: 77 171 247;
  --c-client-soft: #9BD1FB;
  /* Estados */
  --c-success: #2DD4A0;       --c-success-rgb: 45 212 160;
  --c-success-soft: #8EEBC8;
  --c-danger: #F0506E;        --c-danger-rgb: 240 80 110;
  --c-danger-soft: #FF9AA8;
  --c-gold: #F2C14E;          --c-gold-rgb: 242 193 78;
  --c-disabled-bg: #1A2236;
  --c-disabled-text: #5E6880;

  /* ═══ LAS MEDIDAS DE CLOSER (Fase 2, mensaje 146) ═══ */
  /* Botones: todos iguales en toda la app */
  --h-boton: 56px;  --r-boton: 16px;
  /* Campos de texto */
  --h-campo: 52px;  --r-campo: 14px;
  /* Tarjetas y cuadros de ícono */
  --r-tarjeta: 20px;  --r-icono: 12px;
  /* Margen lateral de pantalla */
  --m-pantalla: 20px;

  /* Tokens de los componentes base: apuntan a la paleta */
  --background: var(--c-bg);
  --foreground: var(--c-text);
  --surface: var(--c-surface);
  --surface-elevated: var(--c-elevated);
  --card: var(--c-surface);
  --card-foreground: var(--c-text);
  --popover: var(--c-elevated);
  --popover-foreground: var(--c-text);

  /* Naranja Closer — #FF6B2B */
  --primary: var(--c-primary);
  --primary-foreground: var(--c-bg);           /* texto sobre naranja = fondo oscuro */
  --primary-glow: oklch(0.78 0.18 45);         /* halo más cálido */
  --primary-soft: rgb(var(--c-primary-rgb) / 0.14);  /* fondo suave para chips/avisos */

  /* Secundarios neutrales */
  --secondary: var(--c-elevated);
  --secondary-foreground: var(--c-text);
  --muted: var(--c-surface);
  --muted-foreground: var(--c-text-2);
  --accent: var(--c-elevated);
  --accent-foreground: var(--c-text);

  /* Estados */
  --success: var(--c-success);                 /* verde score 80+ */
  --success-foreground: var(--c-bg);
  --warning: var(--c-gold);                    /* amarillo score 60-79 */
  --warning-foreground: var(--c-bg);
  --destructive: var(--c-danger);              /* rojo score <60 / errores */
  --destructive-foreground: var(--c-text);

  /* Score colors (alias semánticos del feedback) */
  --score-low: var(--c-danger);
  --score-mid: var(--c-gold);
  --score-high: var(--c-success);

  /* Coach — acento azulado frío para diferenciarlo del primario.
     El coach es voz didáctica, no acción. No compite con naranja. */
  --coach: var(--c-client);
  --coach-foreground: var(--c-bg);

  /* Bordes */
  --border: var(--c-border);
  --border-strong: var(--c-border-strong);
  --input: var(--c-border);
  --ring: rgb(var(--c-primary-rgb) / 0.6);

  /* Gradientes */
  --gradient-primary: linear-gradient(135deg, var(--c-primary) 0%, oklch(0.78 0.18 45) 100%);
  --gradient-fire: linear-gradient(180deg, var(--c-primary) 0%, oklch(0.62 0.22 30) 100%);
  --gradient-surface: linear-gradient(180deg, var(--c-elevated) 0%, var(--c-surface) 100%);

  /* Sombras */
  --shadow-orange: 0 10px 30px -8px rgb(var(--c-primary-rgb) / 0.45),
                   0 4px 12px -4px rgb(var(--c-primary-rgb) / 0.3);
  --shadow-card: 0 1px 2px oklch(0 0 0 / 0.4), 0 8px 24px -12px oklch(0 0 0 / 0.5);
  --shadow-elevated: 0 24px 60px -20px oklch(0 0 0 / 0.7);

  --radius: 14px;

  /* Charts */
  --chart-1: var(--c-primary);
  --chart-2: var(--c-success);
  --chart-3: var(--c-gold);
  --chart-4: var(--c-client);
  --chart-5: var(--c-danger);

  /* Sidebar (manager dashboard, fase posterior) */
  --sidebar: var(--c-surface);
  --sidebar-foreground: var(--c-text);
  --sidebar-primary: var(--c-primary);
  --sidebar-primary-foreground: var(--c-bg);
  --sidebar-accent: var(--c-elevated);
  --sidebar-accent-foreground: var(--c-text);
  --sidebar-border: var(--c-border);
  --sidebar-ring: rgb(var(--c-primary-rgb) / 0.6);
}

/* Mantenemos .dark por si shadcn lo referencia, con los mismos tokens */
.dark {
  color-scheme: dark;
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html, body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  /* Forzar dark scheme — Closer es dark-only */
  html {
    color-scheme: dark;
  }

  h1, h2, h3, h4, h5, h6,
  .font-display {
    font-family: var(--font-display);
    letter-spacing: -0.02em;
  }

  /* Scrollbar discreta */
  *::-webkit-scrollbar { width: 8px; height: 8px; }
  *::-webkit-scrollbar-track { background: transparent; }
  *::-webkit-scrollbar-thumb {
    background: oklch(1 0 0 / 0.08);
    border-radius: 99px;
  }
  *::-webkit-scrollbar-thumb:hover { background: oklch(1 0 0 / 0.16); }

  /* Selección con naranja */
  ::selection {
    background: rgb(var(--c-primary-rgb) / 0.35);
    color: var(--color-foreground);
  }
}

/* ────────────────────────────────────────
 * Utilidades semánticas reutilizables
 * ──────────────────────────────────────── */
@layer components {
  /* Contenedor mobile-first canónico — max 560px, padding 1.2rem */
  .container-closer {
    width: 100%;
    max-width: 560px;
    margin-inline: auto;
    padding-inline: 1.2rem;
  }

  /* Card base Closer — radio 14px, fondo surface, border sutil */
  .card-closer {
    background: var(--gradient-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-card);
  }

  /* Halo naranja — para CTAs prominentes */
  .glow-orange {
    box-shadow: var(--shadow-orange);
  }

  /* Texto eyebrow — etiquetas de sección */
  .eyebrow {
    font-family: var(--font-display);
    font-size: 0.7rem;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--color-muted-foreground);
  }

  /* Texto Closer hablando — para mensajes del entrenador */
  .closer-voice {
    font-family: var(--font-display);
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: -0.015em;
  }
}

/* ────────────────────────────────────────
 * Animaciones
 * ──────────────────────────────────────── */
@keyframes pulse-orange {
  0%, 100% { box-shadow: 0 0 0 0 rgb(var(--c-primary-rgb) / 0.5); }
  50% { box-shadow: 0 0 0 12px rgb(var(--c-primary-rgb) / 0); }
}

@keyframes fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slide-down {
  from { opacity: 0; transform: translateY(-12px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes score-fill {
  from { stroke-dashoffset: var(--score-circumference, 283); }
  to { stroke-dashoffset: var(--score-target, 0); }
}

@keyframes breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.03); }
}

@keyframes mic-pulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgb(var(--c-danger-rgb) / 0.6); }
  50% { transform: scale(1.06); box-shadow: 0 0 0 16px rgb(var(--c-danger-rgb) / 0); }
}

.animate-mic-pulse { animation: mic-pulse 1.4s ease-in-out infinite; }

